#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
set set_create(const int *v, size_t n) {
    (void)v;
    (void)n;
    set s = {NULL, 0};
    return s;
}
void set_free(set *s) { free(s->items); }
bool set_contains(const set *s, int v) {
    (void)s;
    (void)v;
    return false;
}
void set_add(set *s, int v) {
    (void)s;
    (void)v;
}
bool set_subset(const set *a, const set *b) {
    (void)a;
    (void)b;
    return false;
}
bool set_disjoint(const set *a, const set *b) { return set_subset(a, b); }
bool set_equal(const set *a, const set *b) { return set_subset(a, b); }
set set_intersection(const set *a, const set *b) {
    (void)a;
    (void)b;
    return set_create(NULL, 0);
}
set set_difference(const set *a, const set *b) { return set_intersection(a, b); }
set set_union(const set *a, const set *b) { return set_intersection(a, b); }

