#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
bool set_contains(const set *s, int v) {
    for (size_t i = 0; i < s->count; i++)
        if (s->items[i] == v)
            return true;
    return false;
}
void set_add(set *s, int v) {
    if (set_contains(s, v))
        return;
    s->items = (int *)realloc(s->items, (s->count + 1) * sizeof(int));
    size_t i = s->count++;
    while (i && s->items[i - 1] > v) {
        s->items[i] = s->items[i - 1];
        i--;
    }
    s->items[i] = v;
}
set set_create(const int *v, size_t n) {
    set s = {NULL, 0};
    for (size_t i = 0; i < n; i++)
        set_add(&s, v[i]);
    return s;
}
void set_free(set *s) {
    free(s->items);
    s->items = NULL;
    s->count = 0;
}
bool set_subset(const set *a, const set *b) {
    for (size_t i = 0; i < a->count; i++)
        if (!set_contains(b, a->items[i]))
            return false;
    return true;
}
bool set_disjoint(const set *a, const set *b) {
    for (size_t i = 0; i < a->count; i++)
        if (set_contains(b, a->items[i]))
            return false;
    return true;
}
bool set_equal(const set *a, const set *b) {
    return a->count == b->count && set_subset(a, b);
}
set set_intersection(const set *a, const set *b) {
    set r = {NULL, 0};
    for (size_t i = 0; i < a->count; i++)
        if (set_contains(b, a->items[i]))
            set_add(&r, a->items[i]);
    return r;
}
set set_difference(const set *a, const set *b) {
    set r = {NULL, 0};
    for (size_t i = 0; i < a->count; i++)
        if (!set_contains(b, a->items[i]))
            set_add(&r, a->items[i]);
    return r;
}
set set_union(const set *a, const set *b) {
    set r = set_create(a->items, a->count);
    for (size_t i = 0; i < b->count; i++)
        set_add(&r, b->items[i]);
    return r;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    int x[] = {3, 1, 1}, y[] = {2, 3};
    set a = set_create(x, 3), b = set_create(y, 2);
    assert(a.count == 2 && a.items[0] == 1);
    set u = set_union(&a, &b), i = set_intersection(&a, &b), d = set_difference(&a, &b);
    assert(u.count == 3 && i.count == 1 && i.items[0] == 3 && d.count == 1 &&
           d.items[0] == 1);
    assert(set_subset(&i, &a) && !set_disjoint(&a, &b) && !set_equal(&a, &b));
    set e = set_create(NULL, 0);
    assert(set_subset(&e, &a) && set_disjoint(&e, &a));
    set_free(&a);
    set_free(&b);
    set_free(&u);
    set_free(&i);
    set_free(&d);
    set_free(&e);

    return 0;
}
